"""Fully synthetic counts generated by the model's OWN generative process.

WHY THIS EXISTS ALONGSIDE THE REAL-TISSUE BUILD. `build_sim_2x2.py` injects four
factors into real MERFISH counts. That keeps the nuisance structure honest, but it
also means the background quadrant is real mouse-brain anatomy, which carries far
more variance than anything we inject and which no generative model of ours
produced. A method can therefore fail here for reasons that have nothing to do
with the 2x2 -- and `haruka_both` did.

This module removes that confound: every factor, the latent space, the decoder and
the counts come from the SAME generative process the model assumes. If a model
cannot recover the factors here, the failure is the model's, because the data was
drawn from exactly its own assumed family.

    z      ~ A_arch[gt_arch]        + noise     background x intrinsic
    z_sp   ~ A_niche[gt_niche]      + noise     background x spatial
    s      ~ A_sint[gt_sal_intr]    + noise     salient    x intrinsic  (treated only)
    s_sp   ~ A_sdom[gt_sal_dom]     + noise     salient    x spatial    (treated only)

    latent   = cat([z, z_sp, s, s_sp])
    px_scale = softmax(MLP(latent) + slice_offset)
    counts   ~ Poisson(library * px_scale)

ONE PREMISE CHANGES FROM THE REAL-DATA BUILD, DELIBERATELY. There, `gt_niche` was
constructed so a cell's own row was independent of its own niche (`haruka_sim.py`'s
rho = 0 regime), and `self_check_2x2` asserted own-AUROC ~ 0.5. Under a generative
process that constraint is simply false: the decoder reads `z_sp`, so the niche IS
written into the cell's own counts. That is what SIMVI means by interaction-induced
state. So the question this build asks is not "which source carries the factor" but
"does each latent recover ITS OWN factor and decline the other three" -- pure
disentanglement, which is what the 2x2 actually claims.

What still holds, and is what makes the niche a *spatial* factor:

  * `gt_niche` is determined by the NEIGHBOURS' sender marks with the cell itself
    excluded, so it is predictable from the neighbourhood and is statistically
    independent of `gt_arch`.
  * `gt_sal_intrinsic` is i.i.d. in space, so neighbourhood pooling cannot help.
  * `gt_sal_domain` is spatially contiguous and present only in the treated arm.
  * All four factors are drawn independently, so any off-diagonal recovery in the
    scoring matrix is the model mixing them, never the data.

    python build_sim_counts.py --deltas 0 0.5 1.0 2.0 --seeds 0 1 2
"""

from __future__ import annotations

import argparse
import json
import os

import anndata as ad
import numpy as np
import pandas as pd
import scipy.sparse as sp
from scipy.ndimage import gaussian_filter
from scipy.spatial import cKDTree

# latent widths per quadrant
D_ARCH, D_NICHE, D_SINT, D_SDOM = 10, 6, 6, 6

K_ARCH = 7          # anatomical-analogue classes
K_NICHE = 3         # niche terciles
K_SINT = 3          # salient intrinsic states (class 0 = null)
K_SDOM = 3          # salient spatial domains (class 0 = outside)

P_SENDER = 0.30
K_NBR = 60          # neighbours pooled for the niche
N_LIGAND = 2

TIMEPOINTS = ["T1", "T2", "T3", "T4"]


def _lattice(n_side: int, rng) -> np.ndarray:
    """Jittered lattice. Jitter so the k-NN graph is not perfectly regular, which
    would make neighbourhood pooling artificially easy."""
    gx, gy = np.meshgrid(np.arange(n_side), np.arange(n_side))
    xy = np.stack([gx.ravel(), gy.ravel()], 1).astype(float)
    return xy + rng.uniform(-0.3, 0.3, xy.shape)


#: Spatial granularity of the parent (architecture / salient-intrinsic) fields.
#: THIS IS THE PARAMETER THAT DECIDES WHETHER THE SPATIAL QUADRANTS ARE TESTABLE.
#: The spatial factors are the residualised neighbourhood composition of their
#: parent, so they only carry variance where a cell's neighbourhood differs from
#: its own class. At the original 0.12 that was true for just 4.3% of cells and the
#: information ceiling -- what a perfect reader could recover -- was R^2 0.31, so
#: the two spatial quadrants could not discriminate between model variants at all.
#: At 0.06 mixed neighbourhoods rise to 10.4% and the ceiling to 0.865.
#: Measured by `tune_ceiling.py`; note that widening `k` makes this WORSE (0.865 ->
#: 0.441 at k=120) because a larger pool averages across more regions.
ARCH_LENGTH_SCALE = 0.06


def _regions(xy: np.ndarray, k: int, rng, grid: int = 128,
             length_scale: float = ARCH_LENGTH_SCALE) -> np.ndarray:
    """`k` contiguous regions from a smooth random field -- the anatomy analogue.

    The SAME field is reused across slices by the caller (one rng draw), so the
    architecture is shared, exactly as real anatomy is shared across animals.
    """
    fields = []
    for _ in range(k):
        f = gaussian_filter(rng.standard_normal((grid, grid)),
                            sigma=length_scale * grid, mode="wrap")
        fields.append((f - f.mean()) / (f.std() + 1e-12))
    u = (xy - xy.min(0)) / np.maximum(xy.max(0) - xy.min(0), 1e-9)
    ij = np.clip((u * (grid - 1)).round().astype(int), 0, grid - 1)
    vals = np.stack([f[ij[:, 1], ij[:, 0]] for f in fields], 1)
    return vals.argmax(1)


def _nbr_factor(xy: np.ndarray, parent: np.ndarray, n_parent: int,
                proj: np.ndarray, k: int = K_NBR, n_out: int = 3):
    """Interaction-induced state: a function of WHAT THE NEIGHBOURS ARE.

    THIS IS THE LOAD-BEARING FIX. The model constructs its spatial latent as
    ``z_sp = GATv2(neighbours' z)``, and ``z`` encodes intrinsic identity
    (``gt_arch``). So for the benchmark to be answerable at all, the niche must be
    a function of the neighbours' INTRINSIC STATE -- which is also exactly what
    SIMVI means by interaction-induced state.

    The previous version drew the niche from an exogenous sender/ligand field and
    -- unlike the real-tissue build, which expressed a 20-gene ligand marker block
    -- never wrote that field into any cell's expression. Measured consequence:

        neighbours' gt_arch composition -> gt_niche :  0.501   (chance)
        neighbours' sender density      -> gt_niche :  0.525

    The factor was structurally unreachable by the architecture, so every
    `spatial -> niche` number was scoring a target no model of this family could
    recover. That is a broken simulator, not a broken model.

    Here the niche is the Gaussian-kernel-weighted composition of neighbouring
    architecture classes WITH THE CELL ITSELF EXCLUDED, projected onto a fixed
    random direction and split into terciles. Self-exclusion keeps a cell's own
    identity from determining its own niche; the neighbourhood is what does.
    """
    n = len(xy)
    kk = min(k, n - 1)
    dist, idx = cKDTree(xy).query(xy, k=kk + 1)
    dist, idx = dist[:, 1:], idx[:, 1:]          # drop self
    bw = np.median(dist[:, kk // 2])
    w = np.exp(-0.5 * (dist / max(bw, 1e-9)) ** 2)
    w = w / np.maximum(w.sum(1, keepdims=True), 1e-9)

    onehot = np.eye(n_parent)[parent]            # (n, n_parent)
    comp = np.einsum("nk,nkc->nc", w, onehot[idx])   # neighbourhood composition

    # RESIDUALISE AGAINST THE CELL'S OWN TYPE. Architecture regions are contiguous,
    # so a cell's neighbourhood composition is dominated by its own class: the raw
    # composition predicted gt_niche from OWN gt_arch at AUROC 0.917 with
    # NMI(arch, niche) = 0.411, i.e. the niche had collapsed into a proxy for
    # architecture and the two quadrants were no longer separable.
    #
    # Subtracting the mean composition of cells sharing this cell's own class
    # leaves the part of the neighbourhood that its own identity does NOT predict
    # -- which is precisely "interaction-induced state not explainable by the
    # cell's own type", and the only version of this factor for which a spatial
    # latent is NECESSARY rather than redundant with the intrinsic one. A GAT can
    # still construct it: the centre cell is the attention query, so its own class
    # is available to subtract.
    for c in range(n_parent):
        m = parent == c
        if m.sum() > 1:
            comp[m] -= comp[m].mean(0, keepdims=True)
    # `proj` is passed in, NOT drawn here. Drawing it per slice made the
    # composition -> niche mapping a DIFFERENT function on every animal, so a
    # leave-one-animal-out probe could not transfer and the factor measured 0.472
    # (chance) even though NMI(gt_arch, gt_niche) was 0.055 -- the dependence
    # existed, it just was not the same dependence twice. Shared across slices,
    # like the codebooks and the decoder.
    score = comp @ proj

    # Terciles WITHIN each architecture class, so P(niche | arch) = 1/3 exactly and
    # any off-diagonal in the scoring matrix is the model mixing the factors rather
    # than the data confounding them.
    label = np.zeros(len(score), dtype=int)
    qs = [(i + 1) / n_out for i in range(n_out - 1)]
    for c in range(n_parent):
        m = parent == c
        if m.sum() >= 2 * n_out:
            label[m] = np.digitize(score[m], np.quantile(score[m], qs))
    return score, label


def _domains(xy: np.ndarray, rng, strata: np.ndarray, area: float = 0.15,
             grid: int = 128, min_stratum: int = 50):
    """Two contiguous spatial domains, BALANCED within each architecture class.

    The domain field and the architecture field are both smooth spatial fields, so
    thresholding the domain globally makes the two correlate: the first version of
    this build measured NMI(gt_arch, gt_sal_domain) = 0.026 and, as a direct
    consequence, the domain was predictable on CONTROL cells at AUROC 0.596 --
    position predicts architecture, architecture drives expression, expression
    predicts the domain, with no effect applied anywhere.

    Thresholding within each architecture class at that class's own quantile makes
    P(domain | arch) constant by construction, which kills both at once. The domain
    stays contiguous because the field is smooth and the selected cells within a
    class are still where the field is high.
    """
    u = (xy - xy.min(0)) / np.maximum(xy.max(0) - xy.min(0), 1e-9)
    ij = np.clip((u * (grid - 1)).round().astype(int), 0, grid - 1)
    lab = np.zeros(len(xy), dtype=int)
    taken = np.zeros(len(xy), dtype=bool)
    classes = np.unique(strata)
    for d in range(K_SDOM - 1):
        f = gaussian_filter(rng.standard_normal((grid, grid)), sigma=0.13 * grid, mode="wrap")
        v = f[ij[:, 1], ij[:, 0]]
        thr_cell = np.full(len(xy), np.quantile(v[~taken], 1 - area))
        for c in classes:
            m = (strata == c) & ~taken
            if m.sum() >= min_stratum:
                thr_cell[strata == c] = np.quantile(v[m], 1 - area)
        hit = (v >= thr_cell) & ~taken
        lab[hit] = d + 1
        taken |= hit
    return lab


def build(delta: float, seed: int, n_side: int, n_genes: int, out_dir: str):
    rng = np.random.default_rng(10_000 + seed)

    # --- shared across slices: architecture field, domains, decoder, codebooks ---
    arch_rng = np.random.default_rng(20_000 + seed)     # architecture
    sint_rng = np.random.default_rng(30_000 + seed)     # salient intrinsic regions
    dec_rng = np.random.default_rng(40_000 + seed)      # decoder + codebooks

    A_arch = dec_rng.normal(0, 1.4, (K_ARCH, D_ARCH))
    niche_proj = dec_rng.normal(0, 1.0, K_ARCH)   # shared across slices
    sdom_proj = dec_rng.normal(0, 1.0, K_SINT)    # shared across slices
    A_niche = dec_rng.normal(0, 1.4, (K_NICHE, D_NICHE))
    A_sint = np.vstack([np.zeros((1, D_SINT)), dec_rng.normal(0, 1.4, (K_SINT - 1, D_SINT))])
    A_sdom = np.vstack([np.zeros((1, D_SDOM)), dec_rng.normal(0, 1.4, (K_SDOM - 1, D_SDOM))])

    d_lat = D_ARCH + D_NICHE + D_SINT + D_SDOM
    n_hidden = 128
    W1 = dec_rng.normal(0, 1.0 / np.sqrt(d_lat), (d_lat, n_hidden))
    b1 = dec_rng.normal(0, 0.1, n_hidden)
    W2 = dec_rng.normal(0, 1.0 / np.sqrt(n_hidden), (n_hidden, n_genes))
    b2 = dec_rng.normal(0, 0.1, n_genes)

    rows = []
    for tp in TIMEPOINTS:
        for cond in ("control", "disease"):
            treated = cond == "disease"
            slice_rng = np.random.default_rng(
                abs(hash((seed, tp, cond))) % (2 ** 31))
            xy = _lattice(n_side, slice_rng)
            n = len(xy)

            # architecture: same field across slices, so it is a shared factor
            gt_arch = _regions(xy, K_ARCH, np.random.default_rng(arch_rng.integers(1 << 30)))
            niche_score, gt_niche = _nbr_factor(xy, gt_arch, K_ARCH, niche_proj,
                                                n_out=K_NICHE)
            # --- SALIENT PAIR, mirroring the BACKGROUND pair -------------------
            # The model hard-codes s_sp = GAT(neighbours' s): the salient spatial
            # latent can only ever be a pooled view of the salient intrinsic one.
            # Generating them as INDEPENDENT draws violated that, and the cost was
            # measured: `haruka_vanilla`, which has no spatial branch and therefore
            # no such conflict, recovered gt_sal_domain at ARI 0.69-0.73, while
            # `haruka_both` -- the configuration built for it -- got 0.00-0.09 and
            # its dedicated `salient_spatial` latent got 0.00-0.02. Asked to carry
            # gt_sal_intrinsic AND to feed a pooled gt_sal_domain, `s` delivered
            # neither.
            #
            # So the salient pair is now built exactly like the background pair:
            # a spatially structured intrinsic factor, and a spatial factor that is
            # the residualised neighbourhood composition of it.
            #
            # COST, stated plainly: gt_sal_intrinsic is no longer i.i.d. in space.
            # It was the one factor neighbourhood smoothing could not help with, and
            # the only thing in the benchmark that penalised "smooth everything".
            # Matching the architecture's nesting assumption means giving that up --
            # a real reduction in what this benchmark can catch, and the honest
            # price of option 2.
            gt_sint_cf = _regions(xy, K_SINT,
                                  np.random.default_rng(sint_rng.integers(1 << 30)))
            sdom_score, gt_sdom_cf = _nbr_factor(xy, gt_sint_cf, K_SINT, sdom_proj,
                                                 n_out=K_SDOM)

            # Counterfactual labels are kept on control cells so the false-positive
            # probes are defined; the FACTORS are switched off there.
            gt_sint = np.where(treated, gt_sint_cf, 0)
            gt_sdom = np.where(treated, gt_sdom_cf, 0)

            # `delta` scales the SALIENT factors only. The two BACKGROUND factors
            # (architecture and niche) are properties of the tissue and are present
            # at fixed strength in both arms, so "effect size" means what it says:
            # how strong the condition-specific perturbation is.
            #
            # The first sweep scaled niche/salient by delta but left architecture at
            # unit scale, which made architecture the WEAKEST factor at high delta.
            # The consequence was unmissable: at delta=2.0 plain PCA recovered
            # gt_niche at ARI 0.996 and gt_arch at 0.064, and its assignment margin
            # went negative (-0.216) purely from clustering the now-dominant wrong
            # factor. Those delta=2.0 numbers measured the imbalance, not the methods.
            z = A_arch[gt_arch] + slice_rng.normal(0, 0.35, (n, D_ARCH))
            z_sp = A_niche[gt_niche] + slice_rng.normal(0, 0.35, (n, D_NICHE))
            s = delta * A_sint[gt_sint] + slice_rng.normal(0, 0.35, (n, D_SINT))
            s_sp = delta * A_sdom[gt_sdom] + slice_rng.normal(0, 0.35, (n, D_SDOM))

            latent = np.concatenate([z, z_sp, s, s_sp], 1)
            h = np.tanh(latent @ W1 + b1)
            logits = h @ W2 + b2
            # per-slice offset = the nuisance a background latent must absorb
            logits = logits + slice_rng.normal(0, 0.25, n_genes)
            px = np.exp(logits - logits.max(1, keepdims=True))
            px /= px.sum(1, keepdims=True)

            library = slice_rng.lognormal(np.log(600), 0.3, size=n)[:, None]
            counts = slice_rng.poisson(library * px).astype(np.float32)

            rows.append(dict(
                counts=counts, xy=xy,
                obs=pd.DataFrame(dict(
                    slice_id=f"{tp}_{cond}", timepoint=tp, condition=cond,
                    gt_arch=gt_arch.astype(str), gt_niche=gt_niche.astype(str),
                    gt_sal_intrinsic=gt_sint_cf.astype(str),
                    gt_sal_domain=gt_sdom_cf.astype(str),
                    gt_sal_intrinsic_active=gt_sint.astype(str),
                    gt_sal_domain_active=gt_sdom.astype(str),
                    # CONTINUOUS truths. The two spatial factors are terciles of a
                    # continuous score, so the tercile LABEL has no natural clusters
                    # and ARI against it is uninterpretable -- measured at ~0.00 for
                    # every method under both GMM and Leiden, while linear probes
                    # read 0.86-0.92. The score itself is the honest target.
                    niche_score=niche_score, sal_domain_score=sdom_score,
                )),
            ))

    X = np.vstack([r["counts"] for r in rows])
    obs = pd.concat([r["obs"] for r in rows], ignore_index=True)
    obs.index = obs.index.astype(str)
    for c in ("slice_id", "timepoint", "condition", "gt_arch", "gt_niche",
              "gt_sal_intrinsic", "gt_sal_domain"):
        obs[c] = pd.Categorical(obs[c])

    out = ad.AnnData(X=sp.csr_matrix(X), obs=obs,
                     var=pd.DataFrame(index=[f"g{i}" for i in range(n_genes)]))
    out.obsm["spatial"] = np.vstack([r["xy"] for r in rows]).astype(np.float32)
    out.layers["counts"] = out.X.copy()

    out.uns["sim2x2"] = dict(
        delta=float(delta), seed=int(seed), source="synthetic_counts",
        n_domains=K_SDOM - 1, n_cells_per_slice=int(n_side ** 2),
        latent_dims=dict(arch=D_ARCH, niche=D_NICHE, sal_intr=D_SINT, sal_dom=D_SDOM),
        k_classes=dict(arch=K_ARCH, niche=K_NICHE, sal_intr=K_SINT, sal_dom=K_SDOM),
        p_sender=P_SENDER, k_nbr=K_NBR, n_timepoints=len(TIMEPOINTS),
        quadrants=dict(background_intrinsic="gt_arch", background_spatial="gt_niche",
                       salient_intrinsic="gt_sal_intrinsic",
                       salient_spatial="gt_sal_domain"),
        note="counts drawn from the model's own generative family: "
             "latent -> tanh MLP -> softmax -> Poisson(library * px). "
             "gt_niche IS present in the cell's own counts by construction -- "
             "the decoder reads z_sp -- so this build tests disentanglement, "
             "not exclusivity of information source.",
    )

    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir, f"simcnt_d{delta:g}_s{seed}.h5ad")
    out.write_h5ad(path, compression="gzip")
    print(json.dumps(dict(path=path, n_obs=int(out.n_obs), n_vars=int(out.n_vars),
                          delta=delta, seed=seed,
                          median_library=float(np.median(X.sum(1))),
                          mean_zero_frac=float((X == 0).mean())), indent=2))
    return path


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--deltas", type=float, nargs="+", default=[0.0, 0.5, 1.0, 2.0])
    ap.add_argument("--seeds", type=int, nargs="+", default=[0])
    ap.add_argument("--n_side", type=int, default=95, help="cells per slice = n_side^2")
    ap.add_argument("--n_genes", type=int, default=300)
    ap.add_argument("--out_dir", default="data")
    args = ap.parse_args()
    for s in args.seeds:
        for d in args.deltas:
            build(d, s, args.n_side, args.n_genes, args.out_dir)


if __name__ == "__main__":
    main()
